import re
from dataclasses import dataclass


class TemplateError(Exception):
    line: int

    def __init__(self, message: str, line: int):
        self.line = line
        super().__init__(f"Line {line}: {message}")


_UNDEFINED = object()
_KEYWORDS = {"and", "or", "not", "true", "false", "none", "in"}
_FILTER_ARITY = {
    "upper": 0,
    "lower": 0,
    "trim": 0,
    "length": 0,
    "first": 0,
    "last": 0,
    "join": 1,
    "truncate": 1,
    "default": 1,
    "raw": 0,
}
_OPEN_TAG = re.compile(r"\{\{|\{%|\{#")
_NAME = re.compile(r"[A-Za-z_][A-Za-z0-9_]*")
_TOKEN = re.compile(
    r"(?P<space>\s+)"
    r"|(?P<string>'[^']*'|\"[^\"]*\")"
    r"|(?P<number>-?[0-9]+)"
    r"|(?P<name>[A-Za-z_][A-Za-z0-9_]*)"
    r"|(?P<symbol>==|!=|[().,|=])"
)


def _integer(source):
    """Avoid Python's configurable decimal-string conversion limit."""
    negative = source.startswith("-")
    digits = source[1:] if negative else source
    value = 0
    for start in range(0, len(digits), 9):
        chunk = digits[start:start + 9]
        value = value * (10 ** len(chunk)) + int(chunk)
    return -value if negative else value


def _integer_text(value):
    try:
        return str(value)
    except ValueError:
        negative = value < 0
        value = abs(value)
        chunks = []
        while value:
            value, remainder = divmod(value, 1_000_000_000)
            chunks.append(remainder)
        if not chunks:
            return "0"
        result = str(chunks.pop())
        result += "".join(f"{chunk:09d}" for chunk in reversed(chunks))
        return "-" + result if negative else result


class _SyntaxError(Exception):
    pass


def _lex(source):
    tokens = []
    position = 0
    while position < len(source):
        match = _TOKEN.match(source, position)
        if match is None:
            raise _SyntaxError(f"Unexpected character {source[position]!r}")
        kind = match.lastgroup
        value = match.group()
        position = match.end()
        if kind == "space":
            continue
        if kind == "string":
            value = value[1:-1]
        elif kind == "symbol":
            kind = value
        tokens.append((kind, value))
    tokens.append(("eof", ""))
    return tokens


class _ExpressionParser:
    def __init__(self, source):
        self.tokens = _lex(source)
        self.position = 0

    def peek(self):
        return self.tokens[self.position]

    def take(self):
        token = self.peek()
        self.position += 1
        return token

    def accept(self, kind, value=None):
        token = self.peek()
        if token[0] == kind and (value is None or token[1] == value):
            self.position += 1
            return True
        return False

    def require(self, kind, value=None):
        token = self.peek()
        if not self.accept(kind, value):
            expected = value if value is not None else kind
            raise _SyntaxError(f"Expected {expected!r}")
        return token[1]

    def name(self):
        token = self.peek()
        if token[0] != "name" or token[1] in _KEYWORDS:
            raise _SyntaxError("Expected a non-keyword name")
        self.position += 1
        return token[1]

    def finish(self):
        if self.peek()[0] != "eof":
            raise _SyntaxError("Unexpected token after expression")

    def expression(self):
        return self.parse_or()

    def parse_or(self):
        node = self.parse_and()
        while self.accept("name", "or"):
            node = ("or", node, self.parse_and())
        return node

    def parse_and(self):
        node = self.parse_not()
        while self.accept("name", "and"):
            node = ("and", node, self.parse_not())
        return node

    def parse_not(self):
        if self.accept("name", "not"):
            return ("not", self.parse_not())
        return self.parse_comparison()

    def parse_comparison(self):
        node = self.parse_filters()
        if self.peek()[0] in ("==", "!="):
            operator = self.take()[0]
            node = (operator, node, self.parse_filters())
            if self.peek()[0] in ("==", "!="):
                raise _SyntaxError("Chained comparisons are not allowed")
        return node

    def parse_filters(self):
        node = self.parse_primary()
        filters = []
        while self.accept("|"):
            name = self.require("name")
            arguments = []
            if self.accept("("):
                if not self.accept(")"):
                    arguments.append(self.expression())
                    while self.accept(","):
                        arguments.append(self.expression())
                    self.require(")")
            if name not in _FILTER_ARITY:
                raise _SyntaxError(f"Unknown filter {name!r}")
            if len(arguments) != _FILTER_ARITY[name]:
                raise _SyntaxError(
                    f"Filter {name!r} expects {_FILTER_ARITY[name]} argument(s)"
                )
            filters.append((name, arguments))
        return ("filters", node, filters) if filters else node

    def parse_primary(self):
        kind, value = self.peek()

        if kind == "number":
            self.take()
            return ("literal", _integer(value))

        if kind == "string":
            self.take()
            return ("literal", value)

        if self.accept("("):
            node = self.expression()
            self.require(")")
            # Preserve parentheses: raw inside them is not an outer raw filter.
            return ("group", node)

        if kind == "name":
            if value in ("true", "false", "none"):
                self.take()
                return ("literal", {
                    "true": True,
                    "false": False,
                    "none": None,
                }[value])

            name = self.name()
            segments = []
            while self.accept("."):
                segment_kind, segment = self.peek()
                if segment_kind == "number" and not segment.startswith("-"):
                    self.take()
                    segments.append((segment, _integer(segment)))
                elif segment_kind == "name" and segment not in _KEYWORDS:
                    self.take()
                    segments.append((segment, None))
                else:
                    raise _SyntaxError("Expected a path segment")
            return ("path", name, segments)

        raise _SyntaxError("Expected an expression")


def _parse_expression(source):
    parser = _ExpressionParser(source)
    expression = parser.expression()
    parser.finish()
    return expression


def _parse_binding(source, is_loop):
    parser = _ExpressionParser(source)
    name = parser.name()
    if is_loop:
        parser.require("name", "in")
    else:
        parser.require("=")
    expression = parser.expression()
    parser.finish()
    return name, expression


@dataclass
class _If:
    branches: list
    otherwise: object
    position: int
    line: int


@dataclass
class _For:
    name: str
    expression: tuple
    body: list
    otherwise: object
    position: int
    line: int


def _scan(template, errors):
    tokens = []
    position = 0
    line = 1
    trim_next = False

    while True:
        match = _OPEN_TAG.search(template, position)
        if match is None:
            text = template[position:]
            if trim_next:
                text = text.lstrip()
            if text:
                tokens.append(("text", text, position, line))
            break

        start = match.start()
        opener = match.group()
        closer = {"{{": "}}", "{%": "%}", "{#": "#}"}[opener]
        gap = template[position:start]
        tag_line = line + gap.count("\n")
        trim_left = template.startswith("-", start + 2)

        text = gap.lstrip() if trim_next else gap
        if trim_left:
            text = text.rstrip()
        if text:
            tokens.append(("text", text, position, line))

        end = template.find(closer, start + 2)
        if end == -1:
            errors.append((start, tag_line, "Tag has no closing delimiter"))
            break

        trim_right = end > start + 2 and template[end - 1] == "-"
        content_start = start + 2 + int(trim_left)
        content_end = end - int(trim_right)
        content = template[content_start:content_end]

        if opener != "{#":
            kind = "output" if opener == "{{" else "block"
            tokens.append((kind, content, start, tag_line))

        next_position = end + 2
        line = tag_line + template[start:next_position].count("\n")
        position = next_position
        trim_next = trim_right

    return tokens


def _compile(template):
    errors = []
    tokens = _scan(template, errors)
    root = []
    current = root
    stack = []

    def report(position, line, message):
        errors.append((position, line, message))

    def expression_or_placeholder(source, position, line):
        try:
            return _parse_expression(source)
        except _SyntaxError as error:
            report(position, line, str(error))
            return ("literal", None)

    for kind, content, position, line in tokens:
        if kind == "text":
            current.append(("text", content))
            continue

        if kind == "output":
            expression = expression_or_placeholder(content, position, line)
            raw = (
                expression[0] == "filters"
                and any(name == "raw" for name, _ in expression[2])
            )
            current.append(("output", expression, raw))
            continue

        source = content.lstrip()
        match = _NAME.match(source)
        if match is None:
            report(position, line, "Expected a block tag name")
            continue

        command = match.group()
        remainder = source[match.end():]

        if command not in {
            "if", "elif", "else", "endif", "for", "endfor", "set"
        }:
            report(position, line, f"Unknown block tag {command!r}")
            continue

        if command in ("if", "elif"):
            expression = expression_or_placeholder(remainder, position, line)

            if command == "if":
                body = []
                node = _If([(expression, body)], None, position, line)
                current.append(node)
                stack.append((node, current))
                current = body
            elif (
                not stack
                or not isinstance(stack[-1][0], _If)
                or stack[-1][0].otherwise is not None
            ):
                report(position, line, "elif does not fit the open block")
            else:
                body = []
                stack[-1][0].branches.append((expression, body))
                current = body
            continue

        if command in ("for", "set"):
            try:
                name, expression = _parse_binding(
                    remainder, is_loop=(command == "for")
                )
            except _SyntaxError as error:
                report(position, line, str(error))
                name, expression = "_", ("literal", None)

            if command == "set":
                current.append(("set", name, expression))
            else:
                body = []
                node = _For(name, expression, body, None, position, line)
                current.append(node)
                stack.append((node, current))
                current = body
            continue

        if remainder.strip():
            report(position, line, f"{command} takes no arguments")

        if command == "else":
            if not stack or stack[-1][0].otherwise is not None:
                report(position, line, "else does not fit the open block")
            else:
                body = []
                stack[-1][0].otherwise = body
                current = body
            continue

        expected = _If if command == "endif" else _For
        if not stack or not isinstance(stack[-1][0], expected):
            report(position, line, f"{command} does not fit the open block")
        else:
            _, current = stack.pop()

    for node, _ in stack:
        report(node.position, node.line, "Block has no closing tag")

    if errors:
        _, line, message = min(errors, key=lambda error: error[0])
        raise TemplateError(message, line)

    return root


def _truth(value):
    return value is not _UNDEFINED and bool(value)


def _equal(left, right):
    if left is _UNDEFINED:
        left = None
    if right is _UNDEFINED:
        right = None

    if type(left) is not type(right):
        return False

    if isinstance(left, list):
        return len(left) == len(right) and all(
            _equal(a, b) for a, b in zip(left, right)
        )

    if isinstance(left, dict):
        if len(left) != len(right):
            return False
        # Include key kinds, so integer and boolean keys stay distinct.
        right_items = {(type(key), key): value for key, value in right.items()}
        for key, value in left.items():
            typed_key = (type(key), key)
            if typed_key not in right_items:
                return False
            if not _equal(value, right_items[typed_key]):
                return False
        return True

    return left == right


def _text(value):
    if value is None or value is _UNDEFINED:
        return ""
    if isinstance(value, str):
        return value
    if isinstance(value, bool):
        return "true" if value else "false"
    if isinstance(value, int):
        return _integer_text(value)
    if isinstance(value, list):
        return ", ".join(_text(item) for item in value)
    if isinstance(value, dict):
        return "[object]"
    return ""


def _escape(text):
    return (
        text.replace("&", "&amp;")
        .replace("<", "&lt;")
        .replace(">", "&gt;")
        .replace('"', "&quot;")
    )


def _apply_filter(name, value, arguments):
    if name == "raw":
        return value
    if name == "default":
        return arguments[0] if value is None or value is _UNDEFINED else value
    if name == "length":
        return len(value) if isinstance(value, (str, list, dict)) else 0
    if name == "first":
        return value[0] if isinstance(value, list) and value else _UNDEFINED
    if name == "last":
        return value[-1] if isinstance(value, list) and value else _UNDEFINED
    if name == "join":
        if isinstance(value, list):
            return _text(arguments[0]).join(_text(item) for item in value)
        return _text(value)

    text = _text(value)
    if name == "upper":
        return text.upper()
    if name == "lower":
        return text.lower()
    if name == "trim":
        return text.strip()
    if name == "truncate":
        limit = arguments[0]
        # Out-of-domain dynamic arguments must not make rendering raise.
        if type(limit) is not int or limit < 3:
            return text
        return text if len(text) <= limit else text[:limit - 3] + "..."

    return value  # Filter names have already been validated.


def _evaluate(expression, variables, ctx):
    kind = expression[0]

    if kind == "literal":
        return expression[1]

    if kind == "group":
        return _evaluate(expression[1], variables, ctx)

    if kind == "path":
        name, segments = expression[1:]
        value = variables[name] if name in variables else ctx.get(name, _UNDEFINED)
        for segment, index in segments:
            if isinstance(value, dict):
                value = value.get(segment, _UNDEFINED)
            elif isinstance(value, list) and index is not None:
                value = value[index] if index < len(value) else _UNDEFINED
            else:
                value = _UNDEFINED
        return value

    if kind == "filters":
        value = _evaluate(expression[1], variables, ctx)
        for name, argument_expressions in expression[2]:
            arguments = [
                _evaluate(argument, variables, ctx)
                for argument in argument_expressions
            ]
            value = _apply_filter(name, value, arguments)
        return value

    if kind == "not":
        return not _truth(_evaluate(expression[1], variables, ctx))

    left = _evaluate(expression[1], variables, ctx)
    right = _evaluate(expression[2], variables, ctx)

    if kind == "and":
        return _truth(left) and _truth(right)
    if kind == "or":
        return _truth(left) or _truth(right)
    if kind == "==":
        return _equal(left, right)
    if kind == "!=":
        return not _equal(left, right)

    return _UNDEFINED


def _execute(nodes, variables, ctx, output):
    for node in nodes:
        if isinstance(node, _If):
            for condition, body in node.branches:
                if _truth(_evaluate(condition, variables, ctx)):
                    _execute(body, variables, ctx, output)
                    break
            else:
                if node.otherwise is not None:
                    _execute(node.otherwise, variables, ctx, output)
            continue

        if isinstance(node, _For):
            saved_variables = variables.copy()
            try:
                value = _evaluate(node.expression, variables, ctx)
                if isinstance(value, list):
                    items = value
                elif isinstance(value, dict):
                    items = list(value)
                else:
                    items = []

                length = len(items)
                if not length:
                    if node.otherwise is not None:
                        _execute(node.otherwise, variables, ctx, output)
                else:
                    for index, item in enumerate(items):
                        variables[node.name] = item
                        variables["loop"] = {
                            "index": index + 1,
                            "index0": index,
                            "first": index == 0,
                            "last": index == length - 1,
                            "length": length,
                        }
                        _execute(node.body, variables, ctx, output)
            finally:
                variables.clear()
                variables.update(saved_variables)
            continue

        kind = node[0]
        if kind == "text":
            output.append(node[1])
        elif kind == "set":
            variables[node[1]] = _evaluate(node[2], variables, ctx)
        elif kind == "output":
            text = _text(_evaluate(node[1], variables, ctx))
            output.append(text if node[2] else _escape(text))


def render(template: str, ctx: dict) -> str:
    nodes = _compile(template)
    output = []
    _execute(nodes, {}, ctx, output)
    return "".join(output)
